export const analyzeAdminImport = (actor: string, id: string, raw: unknown, provider: ImportAnalysisProvider = new OpenAiImportAnalysisProvider()) => analyzeAdminProject(actor, id, raw, provider, importPolicy);
export function analyzeAdminProject<T>(actor: string, id: string, raw: unknown, provider: ImportAnalysisProvider, policy: AdminProjectPolicy<T>) {
    const body = mutation(raw, []);
    return mutateAdminProject(actor, id, body, 'analyze', async (doc, session) => {
        admit(); if (!provider.configured()) throw new AdminImportError(503, 'ADMIN_IMPORT_PROVIDER_UNAVAILABLE');
        if (isActive(doc) || doc.analysis.chunks.some(chunk => chunk.state === 'inflight')) throw conflict('ADMIN_IMPORT_ANALYSIS_ACTIVE');
        if (doc.analysis.issue === 'providerOutcomeUnknown') throw conflict('ADMIN_IMPORT_ANALYSIS_OUTCOME_UNKNOWN');
        if (doc.analysis.generation >= LIMITS.generations) throw conflict('ADMIN_IMPORT_BUDGET_EXHAUSTED');
        // The singleton write serializes capacity decisions across actors and server processes.
        const gate = await getDb()!.collection<{ _id: string; revision: number }>('adminImportAnalysisSlots').updateOne({ _id: 'admission' }, { $inc: { revision: 1 } }, { session });
        if (!gate.matchedCount) throw new AdminImportError(503, 'ADMIN_IMPORT_WORKER_UNAVAILABLE');
        // A newer-format project is never dispatched by this release, so it holds none of its capacity, even with a chunk left in flight.
        if (await collection().countDocuments({ $and: [{ 'analysis.actorId': actor }, occupiedAnalysis, writableDraftFilter] }, { session, limit: 1 })) throw new AdminImportError(429, 'ADMIN_IMPORT_ACTOR_BUSY');
        if (await collection().countDocuments({ $and: [occupiedAnalysis, writableDraftFilter] }, { session, limit: 2 }) >= 2) throw new AdminImportError(429, 'ADMIN_IMPORT_CAPACITY');
        const generation = doc.analysis.generation + 1, chunks: Chunk[] = [];
        const tags = (doc.media?.assets ?? []).filter(asset => asset.state === 'ready' && asset.tags && doc.manifest.files.some(file => file.slotId === asset.slotId)).map(asset => ({ slotId: asset.slotId, tags: structuredClone(asset.tags!) }));
        const addChunk = (slots: string[], album: boolean) => { const index = chunks.length; chunks.push({ index, slots, album, hash: digest({ generation, manifest: doc.manifest, baseline: doc.draft, tags, slots, album }), state: 'pending', attemptId: null, startedAt: null, completedAt: null }); };
        addChunk([], true); for (let offset = 0; offset < doc.manifest.files.length; offset += LIMITS.tracksPerChunk) addChunk(doc.manifest.files.slice(offset, offset + LIMITS.tracksPerChunk).map(file => file.slotId), false);
        if (doc.attemptsUsed + chunks.length > LIMITS.attempts) throw conflict('ADMIN_IMPORT_BUDGET_EXHAUSTED');
        if (doc.analysis.generation) doc.analysisHistory.push(structuredClone(doc.analysis));
        doc.analysis = { state: 'queued', generation, operationId: body.operationId, actorId: actor, grantExpiresAt: new Date(Date.now() + LIMITS.grantMs), baseline: structuredClone(doc.draft), tags, chunks, issue: null, leaseOwner: null, leaseUntil: null };
    }, policy);
}
export const cancelAdminImportAnalysis = (actor: string, id: string, raw: unknown) => mutate(actor, id, mutation(raw, []), 'cancel-analysis', async doc => { if (isActive(doc)) doc.analysis.state = 'cancelled'; });

/** The Draft v2 path a suggestion proposes a value for, or null for a field Draft v2 does not suggest. */
function suggestionPath(suggestion: ImportSuggestion | ImportSuggestionV2): ImportDraftPath | null {
    if (suggestion.scope === 'album') return ['title', 'artists', 'releaseDate'].includes(suggestion.field) ? `album.${suggestion.field as 'title' | 'artists' | 'releaseDate'}` : null;
    return typeof suggestion.slotId === 'string' && ['title', 'trackNumber'].includes(suggestion.field) ? `tracks.${suggestion.slotId}.${suggestion.field as 'title' | 'trackNumber'}` : null;
}
/**
 * Accepts one suggestion into a Draft v2 project: its baseline must still be the current value. In an import the value becomes the
 * administrator's own; a catalog review records no value origins (automation never writes its draft).
 */
function acceptDraftV2Suggestion(doc: AdminImportDocument, draft: ImportDraftV2, suggestion: ImportSuggestion | ImportSuggestionV2) {
    const path = suggestionPath(suggestion); if (!path) throw conflict('ADMIN_IMPORT_SUGGESTION_STALE');
    if (!sameDraftValue(draftValueAt(draft, path), suggestion.baseline)) throw conflict('ADMIN_IMPORT_FIELD_CONFLICT');
    let value: unknown; try { value = parseDraftValue(path, suggestion.value, draft); } catch { throw conflict('ADMIN_IMPORT_SUGGESTION_STALE'); }
    setDraftValue(draft, path, value); if (isImportProject(doc)) markAdministratorValues(doc.draftOrigins ??= {}, [path]);
}
export const adoptAdminImportSuggestions = (actor: string, id: string, raw: unknown) => adoptAdminProjectSuggestions(actor, id, raw, importPolicy);
export function adoptAdminProjectSuggestions<T>(actor: string, id: string, raw: unknown, policy: AdminProjectPolicy<T>) {
    const body = mutation(raw, ['generation', 'selectedIds', 'rejectIds']);
    if (!Number.isInteger(body.generation) || !Array.isArray(body.selectedIds) || !Array.isArray(body.rejectIds) || body.selectedIds.length + body.rejectIds.length < 1 || body.selectedIds.length + body.rejectIds.length > 203 || [...body.selectedIds, ...body.rejectIds].some(value => typeof value !== 'string' || !/^[a-f0-9]{24}$/.test(value)) || new Set([...body.selectedIds, ...body.rejectIds]).size !== body.selectedIds.length + body.rejectIds.length) return invalidImport();
    const selected = body.selectedIds as string[], rejected = body.rejectIds as string[];
    return mutateAdminProject(actor, id, body, 'adopt', async doc => {
        if (doc.analysis.generation !== body.generation) throw conflict('ADMIN_IMPORT_SUGGESTION_STALE');
        const targets = [...selected, ...rejected].map(id => doc.suggestions.find(s => s.id === id && s.generation === body.generation && s.decision === 'pending'));
        if (targets.some(s => !s)) throw conflict('ADMIN_IMPORT_SUGGESTION_STALE');
        // An import accepts only a suggestion its editor shows; a hidden one (such as a stand-in Artist) may still be rejected.
        if (isImportProject(doc)) {
            const shown = new Set(importSuggestionsV2View(doc.suggestions, doc.analysis.generation, new Set(doc.manifest.files.map(file => file.slotId)), doc._id.toHexString()).map(s => s.id));
            if (selected.some(id => !shown.has(id))) throw conflict('ADMIN_IMPORT_SUGGESTION_STALE');
        }
        // Every admitted project is Draft v2 here: policy.convert stored a format-1 project before this change.
        const draft = storedDraftV2(doc), before = structuredClone(draft);
        for (const suggestion of targets as (ImportSuggestion | ImportSuggestionV2)[]) {
            if (selected.includes(suggestion.id)) {
                const path = suggestionPath(suggestion); if (path && policy.readOnlyPaths?.has(path)) invalidImport();
                acceptDraftV2Suggestion(doc, draft, suggestion);
                suggestion.decision = 'accepted';
            } else suggestion.decision = 'rejected';
        }
        const capped = policy.cappedDraft ?? ((value: ImportDraftV2) => value);
        if (!draftWithinSizeLimit(capped(before), capped(draft))) invalidImport();
        doc.decisions = retainBoundDecisions(doc.decisions, draft);
    }, policy);
}

export const importCandidateProjection = { name: 1, title: 1, coverArtId: 1, coverArtUrl: 1, creditRevision: 1, adminRevision: 1, albumId: 1, audioTrackIds: 1, releaseDate: 1, credits: 1, visibility: 1, lifecycleStatus: 1, uploadStatus: 1, publicationStatus: 1, mediaType: 1, s3Key: 1, mediaRepresentation: 1, mediaByteHash: 1, updatedAt: 1 };
const candidateProjection = importCandidateProjection;
/** Lifecycle touches may materialize legacy defaults; they do not change the reviewed content. */
export const importCandidateRevision = (doc: Record<string, any>): string => {
    const stable = (value: any): any => value instanceof ObjectId ? value.toHexString() : value instanceof Date ? value.toISOString() : Array.isArray(value) ? value.map(stable) : value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort().filter(key => value[key] !== undefined).map(key => [key, stable(value[key])])) : value;
    return digest(stable({ ...doc, lifecycleStatus: doc.lifecycleStatus ?? 'ready', visibility: doc.visibility ?? 'public' }));
};
/** Artists and Organizations are matched by name; Albums and Tracks by title. */
const named = (kind: ImportDuplicateCandidate['kind']) => kind === 'artist' || kind === 'organization';
function candidate(kind: ImportDuplicateCandidate['kind'], doc: Record<string, any>): ImportDuplicateCandidate {
    if (doc.visibility !== undefined && doc.visibility !== 'public' && doc.visibility !== 'hidden') return invalidImport();
    return { kind, id: doc._id.toHexString(), label: cleanText(named(kind) ? doc.name : doc.title, 300), revision: importCandidateRevision(doc), albumId: typeof doc.albumId === 'string' && objectId(doc.albumId) ? doc.albumId : null, visibility: doc.visibility === 'hidden' ? 'hidden' : 'public', match: 'name', matchedSlotIds: [], automaticReuse: false };
}
const candidateCollection = { artist: 'artists', organization: 'organizations', album: 'albums', track: 'audioTracks' };
const readyCandidate = (kind: ImportDuplicateCandidate['kind']) => kind === 'track' ? { $and: [readyAudioStorageFilter, { $or: [{ mediaType: 'audio' }, { mediaType: { $exists: false } }] }] }
    : kind === 'artist' ? readyArtistLifecycleFilter : kind === 'organization' ? readyOrganizationLifecycleFilter : readyAlbumLifecycleFilter;
/**
 * Exact case-insensitive name candidates: one query of at most 20 rows per distinct Artist entry name (so one common name cannot
 * hide another entry's candidates), one for the label among ready Organizations, one for the Album title and one for track
 * titles and verified bytes: at most 20 * 20 + 3 * 20 = 460 items. Names are never unique identity keys.
 */
export async function adminImportDuplicateCandidates(actor: string, id: string) {
    return withAdmin(actor, async session => {
        const doc = await collection().findOne({ _id: idValue(id), ...importPurposeFilter }, { session }); if (!doc) throw notFound(); const items: ImportDuplicateCandidate[] = [];
        // Candidates read the same Draft v2 view the editor shows, whatever format stored it.
        const manifest = legacyManifestView(doc.manifest), draft = importDraftV2View(doc.draft, manifest, doc._id.toHexString());
        const groups: { kind: ImportDuplicateCandidate['kind']; values: string[] }[] = [
            ...[...new Set(draft.album.artists.map(entry => entry.name))].map(name => ({ kind: 'artist' as const, values: [name] })),
            { kind: 'organization', values: draft.album.label ? [draft.album.label.name] : [] }, { kind: 'album', values: [draft.album.title] }, { kind: 'track', values: draft.tracks.map(track => track.title) }];
        const hashes = new Set((doc.media?.assets ?? []).filter(asset => asset.state === 'ready' && manifest.files.some(file => file.slotId === asset.slotId)).map(asset => asset.sha256));
        for (const { kind, values: labels } of groups) {
            const values = [...new Set(labels.filter(Boolean))].slice(0, 100); if (!values.length && (kind !== 'track' || !hashes.size)) continue;
            const patterns = values.map(value => new RegExp(`^${value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`, 'i'));
            const matches: Record<string, unknown>[] = [{ [named(kind) ? 'name' : 'title']: { $in: patterns } }];
            if (kind === 'track' && hashes.size) matches.push({ 'mediaByteHash.value': { $in: [...hashes] } });
            const rows = await getDb()!.collection(candidateCollection[kind]).find({ $and: [readyCandidate(kind), { $or: matches }] }, { session, projection: candidateProjection }).sort({ _id: 1 }).limit(20).maxTimeMS(3_000).toArray();
            for (const row of rows) { try {
                const hash = row.mediaByteHash, representation = row.mediaRepresentation;
                const verified = kind === 'track' && typeof hash?.objectKey === 'string' && hash.objectKey.length > 0 && Number.isSafeInteger(hash.byteLength) && hash.byteLength > 0 && typeof hash.etag === 'string' && /^"[^"\r\n]{1,200}"$/.test(hash.etag) && (hash.versionId === null || (typeof hash.versionId === 'string' && hash.versionId.length > 0 && hash.versionId.length <= 1024)) && hash?.algorithm === 'sha256' && /^[a-f0-9]{64}$/.test(hash?.value) && hashes.has(hash.value) && hash.objectKey === row.s3Key && hash.objectKey === representation?.objectKey && hash.byteLength === representation?.byteLength && hash.etag === representation?.etag && hash.versionId === representation?.versionId;
                if (!verified && !values.some(value => value.toLocaleLowerCase() === String(named(kind) ? row.name : row.title).toLocaleLowerCase())) continue;
                items.push({ ...candidate(kind, row), match: verified ? 'sha256' : 'name', matchedSlotIds: kind === 'track' ? draft.tracks.filter(track => verified ? doc.media?.assets.some(asset => asset.slotId === track.slotId && asset.state === 'ready' && asset.sha256 === hash.value && asset.byteLength === hash.byteLength) : track.title.toLocaleLowerCase() === String(row.title).toLocaleLowerCase()).map(track => track.slotId) : [] });
            } catch { /* Malformed legacy metadata cannot become a selectable identity. */ } }
        }
        return { items };
    });
}
/**
 * Saves the review's identity decisions `{scope, slotId, entryKey, action, candidateId, candidateRevision}` as one set: one per
 * Artist entry (by entryKey), the label, the Album and each track. An Artist decision binds its entry's key and name and a label
 * decision the label's name; an explicit Artist or label decision makes that value the administrator's own. Two entries cannot
 * reuse one Artist. A body item without entryKey comes from an outdated editor and asks for a reload (importPolicy).
 */
export function decideAdminImportDuplicates(actor: string, id: string, raw: unknown) {
    // Each item is bounded before the intent is fingerprinted: a decision is one flat record of short strings or nulls.
    const body = mutation(raw, ['decisions']); if (!Array.isArray(body.decisions) || body.decisions.length > DRAFT_V2_LIMITS.decisions || body.decisions.some(item => !boundedJson(item, 1, 1_000))) return invalidImport();
    const reusedArtists = (body.decisions as Record<string, unknown>[]).filter(item => item?.scope === 'artist' && item.action === 'reuse').map(item => item.candidateId);
    if (new Set(reusedArtists).size !== reusedArtists.length) return invalidImport();
    return mutate(actor, id, body, 'decisions', async (doc, session) => {
        const seen = new Set<string>(); const decisions: ImportDecisionV2[] = [], draft = storedDraftV2(doc);
        for (const rawDecision of body.decisions as unknown[]) {
            const decision = record(rawDecision); exact(decision, ['scope', 'slotId', 'entryKey', 'action', 'candidateId', 'candidateRevision']);
            if (!['artist', 'label', 'album', 'track'].includes(decision.scope as string) || !['reuse', 'skip', 'create-distinct'].includes(decision.action as string)) return invalidImport();
            const scope = decision.scope as ImportDecisionV2['scope']; if (scope === 'track' ? typeof decision.slotId !== 'string' || !doc.manifest.files.some(file => file.slotId === decision.slotId) : decision.slotId !== null) return invalidImport();
            // An Artist decision names a current entry; every other scope names none, and a label decision needs a label.
            const entry = scope === 'artist' && uuid(decision.entryKey) ? draft.album.artists.find(item => item.key === (decision.entryKey as string).toLowerCase()) : undefined;
            if (scope === 'artist' ? !entry : decision.entryKey !== null || (scope === 'label' && !draft.album.label)) return invalidImport();
            const key = `${scope}:${decision.slotId}:${entry?.key ?? null}`; if (seen.has(key)) return invalidImport(); seen.add(key);
            if (decision.action === 'reuse') {
                if (!objectId(decision.candidateId) || typeof decision.candidateRevision !== 'string' || !/^[a-f0-9]{64}$/.test(decision.candidateRevision)) return invalidImport();
                const kind = scope === 'label' ? 'organization' : scope;
                const target = await getDb()!.collection(candidateCollection[kind]).findOne({ _id: new ObjectId(decision.candidateId), ...readyCandidate(kind) }, { session, projection: candidateProjection });
                if (!target || candidate(kind, target).revision !== decision.candidateRevision) throw conflict('ADMIN_IMPORT_DUPLICATE_STALE');
                if (scope === 'track' && target.albumId) { const album = (body.decisions as Record<string, unknown>[]).find(d => d.scope === 'album' && d.action === 'reuse'); if (!album || album.candidateId !== target.albumId) throw conflict('ADMIN_IMPORT_TRACK_BELONGS_TO_ALBUM'); }
            } else if (decision.candidateId !== null || decision.candidateRevision !== null) return invalidImport();
            if ((scope === 'artist' || scope === 'label') && decision.action !== 'skip') markAdministratorValues(doc.draftOrigins ??= {}, [scope === 'artist' ? 'album.artists' : 'album.label']);
            const { slotId, action, candidateId, candidateRevision } = decision as unknown as ImportDecisionV2;
            decisions.push({ scope, slotId, action, candidateId, candidateRevision, entryKey: entry?.key ?? null, boundName: entry?.name ?? (scope === 'label' ? draft.album.label!.name : null) });
        }
        doc.decisions = decisions;
    });
}

/** Embedded tags are secondary untrusted evidence and have a separate prompt-size allowance. */
function boundedTags(tags: NonNullable<Analysis['tags']>, slots: string[]) { let bytes = 0; return tags.filter(item => slots.includes(item.slotId)).filter(item => { bytes += Buffer.byteLength(JSON.stringify(item)); return bytes <= 12_000; }); }

/** Serialize deployment-wide reservations before dispatch; uncertain or stopped reservations are not refunded. */
async function reserveDailyAnalysisAttempt(now: Date, session: ClientSession): Promise<boolean> {
    const slots = getDb()!.collection<{ _id: string; revision?: number; attempts?: number }>('adminImportAnalysisSlots');
    const gate = await slots.updateOne({ _id: 'admission' }, { $inc: { revision: 1 } }, { session });
    if (!gate.matchedCount) return false;
    const _id = `daily:${now.toISOString().slice(0, 10)}`;
    const budget = await slots.findOne({ _id }, { session });
    if ((budget?.attempts ?? 0) >= LIMITS.dailyAttempts) return false;
    await slots.updateOne({ _id }, { $inc: { attempts: 1 } }, { session, upsert: true });
    return true;
}

/** One durable chunk per tick. An expired in-flight lease is unknown, never an automatic paid retry. */
export async function runAdminImportWorkerOnce(provider: ImportAnalysisProvider = new OpenAiImportAnalysisProvider(), now = new Date(), signal?: AbortSignal): Promise<boolean> {
    if (signal?.aborted || !importEnabled() || !provider.configured()) return false;
    const worker = randomUUID();
    const claim = await collection().findOneAndUpdate({ $and: [{ $or: [{ 'analysis.state': { $in: ['queued', 'running'] } }, { 'analysis.state': 'cancelled', 'analysis.chunks.state': 'inflight' }] }, { $or: [{ 'analysis.leaseUntil': null }, { 'analysis.leaseUntil': { $lte: now } }] }, writableDraftFilter] }, { $set: { 'analysis.leaseOwner': worker, 'analysis.leaseUntil': new Date(now.getTime() + LIMITS.leaseMs) } }, { sort: { createdAt: 1 }, returnDocument: 'after' });
    const claimed = claim.value; if (!claimed) return false;
    let input: AnalysisInput | undefined, attemptId = randomUUID();
    const session = getDatabaseClient().startSession();
    try {
        await session.withTransaction(async () => {
            input = undefined;
            const doc = await collection().findOne({ _id: claimed._id, 'analysis.leaseOwner': worker }, { session }); if (!doc) return;
            // A newer draft format is never dispatched to the v1 provider prompt; its queued analysis waits for a release that knows it.
            if (!importDraftWritable(doc) || (!isActive(doc) && !doc.analysis.chunks.some(chunk => chunk.state === 'inflight'))) { await collection().updateOne({ _id: doc._id, 'analysis.leaseOwner': worker }, { $set: { 'analysis.leaseOwner': null, 'analysis.leaseUntil': null } }, { session }); return; }
            const analysis = doc.analysis; let issue: ImportIssue = null;
            if (analysis.chunks.some(chunk => chunk.state === 'inflight')) issue = 'providerOutcomeUnknown';
            else if (!analysis.grantExpiresAt || analysis.grantExpiresAt <= now) issue = 'grantExpired';
            else if (doc.attemptsUsed >= LIMITS.attempts) issue = 'budgetExhausted';
            else { try { await touchAdmin(analysis.actorId!, session); } catch (error) { if (!(error instanceof AdminImportError)) throw error; issue = 'permissionLost'; } }
            if (!issue && analysis.chunks.some(chunk => chunk.state === 'pending') && !await reserveDailyAnalysisAttempt(now, session)) issue = 'budgetExhausted';
            if (issue) { analysis.state = 'needsAttention'; analysis.issue = issue; for (const chunk of analysis.chunks) if (chunk.state === 'inflight') chunk.state = 'unknown'; analysis.leaseOwner = null; analysis.leaseUntil = null; }
            else {
                const chunk = analysis.chunks.find(chunk => chunk.state === 'pending');
                if (!chunk) { analysis.state = 'complete'; analysis.leaseOwner = null; analysis.leaseUntil = null; }
                else {
                    analysis.state = 'running'; chunk.state = 'inflight'; chunk.attemptId = attemptId; chunk.startedAt = now; doc.attemptsUsed++;
                    // Luna keeps the v1 prompt until S15: a Draft v2 baseline is sent as its v1 view (the first primary entry names the Artist).
                    const baseline = isDraftV2(analysis.baseline) ? legacyDraftView(analysis.baseline, doc.manifest) : analysis.baseline as ImportDraft;
                    input = { ...(doc.purpose === 'catalogReview' ? { purpose: 'catalogReview' as const } : {}), generation: analysis.generation, chunk: chunk.index, manifest: { rootLabel: doc.manifest.rootLabel, files: chunk.album ? doc.manifest.files : doc.manifest.files.filter(file => chunk.slots.includes(file.slotId)) }, baseline: { album: baseline.album, tracks: chunk.album ? [] : baseline.tracks.filter(track => chunk.slots.includes(track.slotId)) }, slots: chunk.slots, album: chunk.album, tags: boundedTags(analysis.tags ?? [], chunk.album ? doc.manifest.files.slice(0, 10).map(file => file.slotId) : chunk.slots) };
                }
            }
            doc.revision++; doc.updatedAt = now; await collection().replaceOne({ _id: doc._id, revision: doc.revision - 1, 'analysis.leaseOwner': worker }, doc, { session });
        }, { writeConcern: { w: 'majority' } });
    } finally { await session.endSession(); }
    if (!input) return true;
    if (signal?.aborted) { await collection().updateOne({ _id: claimed._id, 'analysis.leaseOwner': worker, 'analysis.chunks': { $elemMatch: { attemptId, state: 'inflight' } } }, { $set: { 'analysis.chunks.$.state': 'pending', 'analysis.chunks.$.attemptId': null, 'analysis.chunks.$.startedAt': null, 'analysis.state': 'queued', 'analysis.leaseOwner': null, 'analysis.leaseUntil': null }, $inc: { attemptsUsed: -1, revision: 1 } }); return true; }
    const dispatchedInput = input as AnalysisInput; let suggestions: Awaited<ReturnType<ImportAnalysisProvider['analyze']>> = [], failure: ImportIssue = null;
    try { suggestions = await provider.analyze(dispatchedInput, signal); }
    catch (error) { failure = error instanceof ImportProviderError ? error.issue : 'providerOutcomeUnknown'; }
    const finish = getDatabaseClient().startSession();
    try {
        await finish.withTransaction(async () => {
            const doc = await collection().findOne({ _id: claimed._id, 'analysis.leaseOwner': worker, 'analysis.generation': dispatchedInput.generation }, { session: finish }); if (!doc) return;
            const chunk = doc.analysis.chunks.find(chunk => chunk.attemptId === attemptId && chunk.state === 'inflight'); if (!chunk) return;
            let issue: ImportIssue = failure; try { await touchAdmin(doc.analysis.actorId!, finish); } catch (error) { if (!(error instanceof AdminImportError)) throw error; issue = 'permissionLost'; }
            chunk.completedAt = new Date(); chunk.state = issue ? (issue === 'providerOutcomeUnknown' ? 'unknown' : 'failed') : 'complete';
            if (!issue) {
                const importId = doc._id.toHexString(), ids = suggestions.map((_suggestion, index) => digest({ importId, generation: dispatchedInput.generation, chunk: chunk.index, index }).slice(0, 24));
                if (isDraftV2Document(doc)) {
                    // Suggestions are stored against the Draft v2 baseline; an unusable Artist name drops only itself, and ids keep their indexes.
                    const stored = doc.analysis.baseline ?? doc.draft, baseline = isDraftV2(stored) ? stored : importDraftV2FromV1(stored as ImportDraft, importId);
                    suggestions.forEach((suggestion, index) => { const mapped = draftV2Suggestion(suggestion, baseline, { importId, suggestionId: ids[index] }); if (mapped) doc.suggestions.push({ ...mapped, id: ids[index], generation: dispatchedInput.generation, decision: 'pending' }); });
                } else doc.suggestions.push(...suggestions.map((suggestion, index) => ({ ...suggestion, id: ids[index], generation: dispatchedInput.generation, decision: 'pending' as const })));
            }
            if (doc.analysis.state !== 'cancelled') { doc.analysis.state = issue ? 'needsAttention' : doc.analysis.chunks.every(chunk => chunk.state === 'complete') ? 'complete' : 'queued'; doc.analysis.issue = issue; }
            else if (issue) doc.analysis.issue = issue;
            doc.analysis.leaseOwner = null; doc.analysis.leaseUntil = null; doc.revision++; doc.updatedAt = new Date();
            await collection().replaceOne({ _id: doc._id, revision: doc.revision - 1, 'analysis.leaseOwner': worker }, doc, { session: finish });
        }, { writeConcern: { w: 'majority' } });
    } finally { await finish.endSession(); }
    return true;
}

/** Process-independent persisted queue; closing HTTP observers never cancels admitted work. */
export function startAdminImportWorker(provider: ImportAnalysisProvider = new OpenAiImportAnalysisProvider(), intervalMs = 2_000, track?: AdminWorkTracker): () => Promise<void> {
    return startAdminWorker(signal => runAdminImportWorkerOnce(provider, new Date(), signal), intervalMs, track);
}
